	if servers.next == 0 {
		servers.next = 42<<16 + 1
	}
	sd := servers.next
	servers.next++
	ts := &tsnet.Server{}
	processLogs.mu.Lock()
	ts.Logtail = processLogs.logger
	processLogs.mu.Unlock()
	if ts.Logtail != nil {
		// Latchkey (R29): tsnet's user-facing lines (the login link, every
