/// A confirmation dialog's button, by identifier where SwiftUI carries it
/// through and by label inside the dialog where it does not.
private func confirmationButton(_ app: XCUIApplication, _ id: String, label: String) -> XCUIElement {
    let byID = app.buttons[id]
    if byID.waitForExistence(timeout: 2) { return byID }
    let inSheet = app.sheets.buttons[label]
    if inSheet.exists { return inSheet }
